INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('78427cd1-b307-4a3d-b4ff-bf943bfa71dd', (SELECT id FROM ai.conversations WHERE user_id = '33aa6c6e-bcbc-4356-883b-a63d21076055' AND thread_id = '7b2ce92b-bba3-453d-a84f-5f7e7cea1262'), 'assistant', 'Bu zor duygularla yalnız başa çıkmak zorunda değilsiniz. Yanınızda size destek olabilecek bir yakınınız ya da bir profesyonel bulunuyor. Lütfen onlarla iletişime geçin.', '{"disclosures": ["Acil bir tehlike varsa 112''yi arayın. Sosyal Destek Hattı 183, 7/24 ücretsizdir ve psikososyal destek sağlar."], "target_agent": "HUMAN_HANDOFF", "context_topic": null, "primary_intent": "DISTRESS", "compliance_verdict": "PASS"}', '2026-09-01T22:16:32.014279+00:00') ON CONFLICT DO NOTHING;
