INSERT INTO ai.messages ("id", "conversation_id", "role", "content", "meta", "created_at") VALUES ('c9f79bb6-51d2-4131-926a-8d8b6389cb3a', (SELECT id FROM ai.conversations WHERE user_id = '33aa6c6e-bcbc-4356-883b-a63d21076055' AND thread_id = '7b2ce92b-bba3-453d-a84f-5f7e7cea1262'), 'assistant', 'Şu anda çok zor bir durumla karşı karşıyasınız ve yalnız değilsiniz. Bu duygularla tek başınıza mücadele etmenize gerek yok. Lütfen güvendiğiniz bir yakınınıza ya da bir profesyonel destek hattına ulaşın. Yardım almak, kendinizi daha iyi hissetmenize yardımcı olabilir.', '{"disclosures": ["Acil bir tehlike varsa 112''yi arayın. Sosyal Destek Hattı 183, 7/24 ücretsizdir ve psikososyal destek sağlar."], "target_agent": "HUMAN_HANDOFF", "context_topic": null, "primary_intent": "SELF_HARM", "compliance_verdict": "PASS"}', '2026-09-01T22:17:02.989188+00:00') ON CONFLICT DO NOTHING;
